    slot: slotId, enabled: true, connection, model: String(pick.model),
    maxTokens: ownMax || slot.maxTokens || 1024,
    timeoutMs: slot.timeoutMs || 60000,
    retries: Number.isInteger(slot.retries) ? slot.retries : 2,
    source, envName,
