function abortableSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal && signal.aborted) { reject(aiError('aborted')); return; }
    const t = setTimeout(() => { if (signal) signal.removeEventListener('abort', onAbort); resolve(); }, ms);
    function onAbort() { clearTimeout(t); reject(aiError('aborted')); }
    if (signal) signal.addEventListener('abort', onAbort, { once: true });
  });
}

/** One request with the adapter's retry, timeout and redirect rules. Resolves the parsed JSON. */
async function send(route, url, headers, body, signal, deps) {
  const retries = Number.isInteger(route.retries) ? route.retries : 2;
  const sleep = deps.sleep || abortableSleep;
  for (let attempt = 0; ; attempt++) {
    const timeout = AbortSignal.timeout(route.timeoutMs || 60000);
    const sig = signal ? AbortSignal.any([signal, timeout]) : timeout;
    let res = null;
    let failure = null;
    try {
      res = await deps.fetchImpl(url, {
        method: body === undefined ? 'GET' : 'POST',
        headers: body === undefined ? headers : { 'content-type': 'application/json', ...headers },
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: sig,
        redirect: 'manual',
      });
    } catch (e) {
      failure = e;
    }
    if (signal && signal.aborted) throw aiError('aborted');
    let code;
    let status = 0;
    let wait = null;
    if (failure) {
      code = classifyError(null, null, failure.name === 'AbortError' && timeout.aborted ? { name: 'TimeoutError' } : failure);
    } else {
      status = res.type === 'opaqueredirect' ? 0 : Number(res.status) || 0;
      if (status >= 200 && status < 300) {
        let j;
        try { j = await res.json(); } catch { throw aiError('bad_response', status); }
        if (!j || typeof j !== 'object') throw aiError('bad_response', status);
        return j;
      }
      let errBody = null;
      try { errBody = await res.json(); } catch { errBody = null; }
      code = classifyError(status, errBody, null);
      const raw = res.headers && typeof res.headers.get === 'function' ? res.headers.get('retry-after') : null;
      const ra = raw === null || raw === undefined || String(raw).trim() === '' ? NaN : Number(raw);
      if (Number.isFinite(ra) && ra >= 0) wait = ra * 1000;
    }
    if (!RETRYABLE.includes(code) || attempt >= retries) throw aiError(code, status || undefined);
    await sleep(Math.min(wait ?? 500 * 2 ** attempt, 8000), signal);
  }
}

function textOf(blocks) {
  return (Array.isArray(blocks) ? blocks : []).filter((b) => b && b.type === 'text').map((b) => b.text).join('');
}

/** Anthropic-shaped message → OpenAI chat messages (text, tool calls and tool results only). */
function toOpenAiMessages(m) {
  const role = m && m.role === 'assistant' ? 'assistant' : 'user';
  if (typeof m.content === 'string') return [{ role, content: m.content }];
  const blocks = Array.isArray(m.content) ? m.content : [];
  const text = textOf(blocks);
  if (role === 'assistant') {
    const calls = blocks.filter((b) => b && b.type === 'tool_use').map((b) => ({
      id: b.id, type: 'function', function: { name: b.name, arguments: JSON.stringify(b.input ?? {}) },
    }));
    return [{ role, content: text || null, ...(calls.length ? { tool_calls: calls } : {}) }];
  }
  const out = blocks.filter((b) => b && b.type === 'tool_result').map((b) => ({
    role: 'tool', tool_call_id: b.tool_use_id,
    content: typeof b.content === 'string' ? b.content : textOf(b.content) || JSON.stringify(b.content ?? ''),
  }));
  if (text) out.push({ role: 'user', content: text });
  return out;
}

const STOP_FROM_OPENAI = { stop: 'end_turn', length: 'max_tokens', tool_calls: 'tool_use', function_call: 'tool_use', content_filter: 'refusal' };

/**
 * One chat call. `req.messages` (and `req.system`, string or text blocks) are Anthropic-shaped;
 * `req.tools` are client tools `{name, description, input_schema}`; `req.serverTools` are
 * Anthropic server tools, sent after the client tools and only on an Anthropic connection.
 * Returns `content` as Anthropic blocks whatever the provider, so a tool loop can append it.
 */
async function chat(route, req, deps) {
  if (!route || !route.enabled) throw aiError(route && route.reason ? route.reason : 'not_configured');
  const r = req || {};
  const conn = route.connection;
  const key = deps.getSecret ? deps.getSecret(conn.keyName) : null;
  const maxTokens = Number.isInteger(r.maxTokens) && r.maxTokens > 0 ? r.maxTokens : route.maxTokens;
  const clientTools = Array.isArray(r.tools) ? r.tools : [];
  if (conn.kind === 'anthropic') {
    if (!key) throw aiError('key_missing');
    const tools = [...clientTools, ...(Array.isArray(r.serverTools) ? r.serverTools : [])];
    const body = { model: route.model, max_tokens: maxTokens };
    if (r.temperature !== undefined) body.temperature = r.temperature;
    if (r.system !== undefined) body.system = r.system;
    body.messages = r.messages;
    if (tools.length) body.tools = tools;
    const j = await send(route, `${conn.baseUrl}/v1/messages`, { 'x-api-key': key, 'anthropic-version': '2023-06-01' }, body, r.signal, deps);
    const content = Array.isArray(j.content) ? j.content : [];
    const u = j.usage && typeof j.usage === 'object' ? j.usage : {};
    return {
      text: textOf(content), content,
      toolCalls: content.filter((b) => b && b.type === 'tool_use').map((b) => ({ id: b.id, name: b.name, input: b.input })),
      stopReason: typeof j.stop_reason === 'string' ? j.stop_reason : null,
      usage: { in: u.input_tokens || 0, out: u.output_tokens || 0, searches: (u.server_tool_use && u.server_tool_use.web_search_requests) || 0 },
      model: route.model, providerModel: typeof j.model === 'string' ? j.model : null, connectionId: conn.id,
    };
  }
  if (conn.id === 'openai' && !key) throw aiError('key_missing');
  const messages = [];
  const sys = typeof r.system === 'string' ? r.system : textOf(r.system);
  if (sys) messages.push({ role: 'system', content: sys });
  for (const m of Array.isArray(r.messages) ? r.messages : []) messages.push(...toOpenAiMessages(m));
  const body = { model: route.model, max_tokens: maxTokens };
  if (r.temperature !== undefined) body.temperature = r.temperature;
  body.messages = messages;
  if (clientTools.length) {
    body.tools = clientTools.map((t) => ({ type: 'function', function: { name: t.name, description: t.description, parameters: t.input_schema } }));
  }
  const j = await send(route, `${conn.baseUrl}/chat/completions`, key ? { authorization: `Bearer ${key}` } : {}, body, r.signal, deps);
  const choice = Array.isArray(j.choices) && j.choices[0] ? j.choices[0] : null;
  if (!choice || !choice.message) throw aiError('bad_response');
  const text = typeof choice.message.content === 'string' ? choice.message.content : '';
  const content = text ? [{ type: 'text', text }] : [];
  const toolCalls = [];
  for (const tc of Array.isArray(choice.message.tool_calls) ? choice.message.tool_calls : []) {
    let input = {};
    try { input = JSON.parse(tc.function && tc.function.arguments ? tc.function.arguments : '{}'); } catch { input = {}; }
    const call = { id: tc.id, name: tc.function ? tc.function.name : '', input };
    toolCalls.push(call);
    content.push({ type: 'tool_use', ...call });
  }
  const u = j.usage && typeof j.usage === 'object' ? j.usage : {};
  return {
    text, content, toolCalls,
    stopReason: STOP_FROM_OPENAI[choice.finish_reason] || (toolCalls.length ? 'tool_use' : 'end_turn'),
    usage: { in: u.prompt_tokens || 0, out: u.completion_tokens || 0, searches: 0 },
    model: route.model, providerModel: typeof j.model === 'string' ? j.model : null, connectionId: conn.id,
  };
}

function decodeVector(v) {
  if (Array.isArray(v)) return v.every((x) => typeof x === 'number' && Number.isFinite(x)) ? v : null;
  if (typeof v !== 'string') return null;
  let bin;
  try { bin = atob(v); } catch { return null; }
  if (bin.length % 4 !== 0) return null;
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return Array.from(new Float32Array(bytes.buffer));
}

/** Embed texts on the route's OpenAI-compatible connection. Vectors come back in input order.
 *  Asks for base64 (what the OpenAI SDK asks for, so the stored floats are the same bits) and
 *  accepts a plain float array from a server that ignores the request. */
async function embed(route, texts, opts, deps) {
  if (!route || !route.enabled) throw aiError(route && route.reason ? route.reason : 'not_configured');
  const conn = route.connection;
  if (conn.kind !== 'openai-compatible') throw aiError('needs_unmet');
  const list = (Array.isArray(texts) ? texts : []).map((t) => String(t ?? ''));
  if (!list.length) return { vectors: [], dim: 0, model: route.model, usage: { in: 0 } };
  const key = deps.getSecret ? deps.getSecret(conn.keyName) : null;
  if (conn.id === 'openai' && !key) throw aiError('key_missing');
  const body = { model: route.model, input: list.length === 1 ? list[0] : list, encoding_format: 'base64' };
  // A model that accepts it can be asked for a shorter vector.
  if (opts && Number.isInteger(opts.dimensions) && opts.dimensions > 0) body.dimensions = opts.dimensions;
  const j = await send(route, `${conn.baseUrl}/embeddings`, key ? { authorization: `Bearer ${key}` } : {}, body, opts && opts.signal, deps);
  const rows = Array.isArray(j.data) ? [...j.data].sort((a, b) => (a && b ? (a.index ?? 0) - (b.index ?? 0) : 0)) : [];
  const vectors = rows.map((d) => decodeVector(d && d.embedding));
  if (vectors.length !== list.length || vectors.some((v) => !v || !v.length)) throw aiError('bad_response');
  return { vectors, dim: vectors[0].length, model: route.model, usage: { in: (j.usage && j.usage.prompt_tokens) || 0 } };
}

/** Detect: the model ids a connection serves, reduced to safe ids (≤ 500, sorted). */
async function listModels(connection, deps) {
  const key = deps.getSecret ? deps.getSecret(connection.keyName) : null;
  const route = { timeoutMs: 10000, retries: 0 };
  const ids = [];
  if (connection.kind === 'anthropic') {
    if (!key) throw aiError('key_missing');
    let after = null;
    for (let page = 0; page < 5; page++) {
      const q = `limit=1000${after ? `&after_id=${encodeURIComponent(after)}` : ''}`;
      const j = await send(route, `${connection.baseUrl}/v1/models?${q}`, { 'x-api-key': key, 'anthropic-version': '2023-06-01' }, undefined, null, deps);
      for (const m of Array.isArray(j.data) ? j.data : []) if (m && typeof m.id === 'string') ids.push(m.id);
      if (!j.has_more || typeof j.last_id !== 'string') break;
      after = j.last_id;
    }
  } else {
    const j = await send(route, `${connection.baseUrl}/models`, key ? { authorization: `Bearer ${key}` } : {}, undefined, null, deps);
    for (const m of Array.isArray(j.data) ? j.data : []) if (m && typeof m.id === 'string') ids.push(m.id);
  }
  const models = [...new Set(ids.filter((id) => id.length <= 128 && /^[\w.:/@-]+$/.test(id)))].sort().slice(0, 500);
  return { models };
}

/** Test: one tiny real request through a route. A fixed code plus measured latency, never text. */
async function probe(route, deps) {
  const now = deps.now || (() => Date.now());
  const t0 = now();
  try {
    if (route && route.enabled && route.connection.kind === 'openai-compatible' && route.slot === 'embeddings') {
      const r = await embed(route, ['probe'], {}, deps);
      return { ok: true, code: 'ok', latencyMs: now() - t0, dim: r.dim };
    }
    await chat(route, { messages: [{ role: 'user', content: 'Reply with the single word: ok' }], maxTokens: 5 }, deps);
    return { ok: true, code: 'ok', latencyMs: now() - t0 };
  } catch (e) {
    return { ok: false, code: e && e.name === 'AiError' ? e.code : 'network', latencyMs: now() - t0 };
  }
}

/** A route for an embedder that is not saved yet — the memory panel's candidate. */
function candidateEmbedRoute(connection, model, timeoutMs = 15000) {
  if (!connection || typeof model !== 'string' || !/^[\w.:/@-]{1,128}$/.test(model)) return null;
  if (connection.kind !== 'openai-compatible') return { slot: 'embeddings', enabled: false, reason: 'needs_unmet' };
  return { slot: 'embeddings', enabled: true, connection, model, timeoutMs, retries: 0, source: 'db', envName: null };
}

/** The AI page's Detect / Test, one call: op 'detect' lists a connection's models; op 'test'
 *  probes a resolved route; op 'embed' embeds one short string on a route (a candidate
 *  embedder) and reports the vector's length — optionally asking for `dimensions`.
 *  `target` is that connection or route (null = none). A fixed code, ids and numbers — never
 *  provider text. */
async function runCheck(op, target, deps, opts = {}) {
  if (!target) return { ok: false, code: 'not_configured' };
  if (op === 'embed') {
    if (!target.enabled) return { ok: false, code: target.reason || 'not_configured' };
    const now = deps.now || (() => Date.now());
    const t0 = now();
    try {
      const r = await embed(target, ['probe'], { dimensions: opts.dimensions }, deps);
      return { ok: true, code: 'ok', latencyMs: now() - t0, dim: r.dim };
    } catch (e) {
      return { ok: false, code: e && e.name === 'AiError' ? e.code : 'network', latencyMs: now() - t0 };
    }
  }
  if (op === 'detect') {
    try { return { ok: true, code: 'ok', models: (await listModels(target, deps)).models }; }
    catch (e) { return { ok: false, code: e && e.name === 'AiError' ? e.code : 'network' }; }
  }
  if (!target.enabled) return { ok: false, code: target.reason || 'not_configured' };
  return probe(target, deps);
}

// A failure that will not fix itself by retrying: alarmed on the FIRST occurrence (one operator
// alert). Everything else is alarmed only on a RUN of HEALTH_RUN — one network blip or one
// 5xx is ordinary, and a channel that cries wolf gets muted.
const HARD_CODES = ['key_rejected', 'key_missing', 'quota', 'model_not_found'];
const HEALTH_RUN = 3;

/**
 * A slot's health after one call — pure; the wrapper keeps the state per slot and sends the alert.
 * `prev` is the last value this returned (or null); `outcome` is `{ok: true}` or `{ok: false,
 * code}`; `at` is an ISO time. Returns `{health, alert}`, where `alert` is null, or the code to
 * alarm on ('failing' for a run). One alert per failure episode: `alerted` stays set until a
 * call succeeds.
 */
function nextHealth(prev, outcome, at) {
  const p = prev && typeof prev === 'object' ? prev : { consecutive: 0, failingSince: null, lastCode: null, lastOkAt: null, alerted: false };
  if (outcome && outcome.ok) return { health: { consecutive: 0, failingSince: null, lastCode: null, lastOkAt: at, alerted: false }, alert: null };
  const code = outcome && ERROR_CODES.includes(outcome.code) ? outcome.code : 'http_error';
  const consecutive = p.consecutive + 1;
  const hard = HARD_CODES.includes(code);
  const due = !p.alerted && (hard || consecutive >= HEALTH_RUN);
  return {
    health: { consecutive, failingSince: p.failingSince || at, lastCode: code, lastOkAt: p.lastOkAt, alerted: p.alerted || due },
    alert: due ? (hard ? code : 'failing') : null,
  };
}

/** What the page's chip says about a health record: 'ok', 'failing' (a hard code, or a run), or
 *  'flaky' (failed lately, not yet a run). */
function healthStatus(h) {
  if (!h || !h.consecutive) return 'ok';
  return HARD_CODES.includes(h.lastCode) || h.consecutive >= HEALTH_RUN ? 'failing' : 'flaky';
}

const AI_ADAPTER = Object.freeze({
  PRODUCT_SLOTS, BUILTIN_CONNECTIONS, ERROR_CODES,
  renderTemplate, automodRequest, parseAutomodVerdict, resolveRoute, findConnection, candidateEmbedRoute, chat, embed, listModels, probe, runCheck, classifyError, nextHealth, healthStatus,
});

module.exports = { AI_ADAPTER };
